def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    my = [0] * n
    op = [0] * n
    opp_c_total = 0
    for i in range(n):
        if history[i][0] == 'C':
            my[i] = 0
        else:
            my[i] = 1
        if history[i][1] == 'C':
            op[i] = 0
            opp_c_total += 1
        else:
            op[i] = 1

    overall_coop = opp_c_total / float(n)
    w8 = min(n, 8)
    w15 = min(n, 15)
    recent8_coop = sum(1 for i in range(n - w8, n) if op[i] == 0) / float(w8)
    recent15_coop = sum(1 for i in range(n - w15, n) if op[i] == 0) / float(w15)

    denC = 0
    numC = 0
    denD = 0
    numD = 0
    for i in range(n - 1):
        if my[i] == 0:
            denC += 1
            if op[i + 1] == 0:
                numC += 1
        else:
            denD += 1
            if op[i + 1] == 0:
                numD += 1

    windowD = 25
    startD = n - windowD
    if startD < 0:
        startD = 0
    recent_d_den = 0
    recent_d_num = 0
    for i in range(startD, n - 1):
        if my[i] == 1:
            recent_d_den += 1
            if op[i + 1] == 0:
                recent_d_num += 1

    last_d_success = False
    for i in range(n - 2, -1, -1):
        if my[i] == 1:
            last_d_success = (op[i + 1] == 0)
            break

    recent_exploit = False
    if recent_d_den > 0 and recent_d_num * 3 >= recent_d_den * 2:
        recent_exploit = True
    if last_d_success and (denD <= 2 or recent_d_num > 0) and overall_coop > 0.65 and recent8_coop > 0.70:
        recent_exploit = True

    opp_d_run = 0
    for x in reversed(op):
        if x == 1:
            opp_d_run += 1
        else:
            break

    my_c_run = 0
    for x in reversed(my):
        if x == 0:
            my_c_run += 1
        else:
            break

    cc_run = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 0 and op[i] == 0:
            cc_run += 1
        else:
            break

    hostile = False
    if opp_d_run >= 2 and overall_coop < 0.12 and recent8_coop < 0.15:
        hostile = True
    if opp_d_run >= 4 and overall_coop < 0.25 and recent15_coop < 0.35:
        hostile = True
    if n >= 20 and overall_coop < 0.30 and recent8_coop < 0.30:
        hostile = True
    if recent8_coop == 0.0 and opp_d_run >= 8 and overall_coop < 0.40:
        hostile = True

    if hostile:
        return 'D'

    if my[-1] == 1 and op[-1] == 0 and not recent_exploit:
        return 'C'

    if op[-1] == 1:
        if my[-1] == 1:
            if overall_coop < 0.15 or recent8_coop < 0.15:
                return 'D'
            return 'C'
        else:
            if opp_d_run == 1:
                if overall_coop >= 0.50 or recent8_coop >= 0.55:
                    return 'C'
                return 'D'
            if opp_d_run >= 2 and my_c_run >= 2:
                return 'D'
            if overall_coop >= 0.35 and recent15_coop >= 0.20:
                return 'C'
            return 'D'

    if recent_exploit and op[-1] == 0 and overall_coop > 0.30 and recent8_coop > 0.20:
        return 'D'

    if my[-1] == 0 and op[-1] == 0 and 12 <= n <= 85:
        if cc_run >= 12 and recent8_coop > 0.70 and overall_coop > 0.65:
            if denD == 0 and recent_d_den == 0:
                return 'D'
            if denD == 1 and numD == 0 and recent8_coop > 0.80 and overall_coop > 0.70:
                return 'D'
            if denD == 2 and numD == 0 and cc_run >= 28 and recent8_coop > 0.85 and overall_coop > 0.80:
                return 'D'

    pC = (numC + 1.6) / (denC + 2.0)
    failD = denD - numD
    pD = (numD + 0.15) / (denD + 1.0 + 1.5 * failD)

    pair_prior = 0.78 if op[-1] == 0 else 0.22
    base_now = pC if my[-1] == 0 else pD
    p_now = 0.65 * pair_prior + 0.35 * base_now

    pair_den0 = 0
    pair_num0 = 0
    for i in range(n - 1):
        if my[i] == my[-1] and op[i] == op[-1]:
            pair_den0 += 1
            if op[i + 1] == 0:
                pair_num0 += 1
    if pair_den0 > 0:
        p_now = 0.65 * ((pair_num0 + 2.0 * pair_prior) / (pair_den0 + 2.0)) + 0.35 * base_now

    remaining = 100 - n
    if remaining <= 0:
        return 'D'

    vc = [0.0] * (remaining + 1)
    vd = [0.0] * (remaining + 1)
    for t in range(1, remaining + 1):
        vC = 3.0 * pC + vc[t - 1]
        vD = 1.0 + 4.0 * pC + vd[t - 1]
        vc[t] = vC if vC >= vD else vD

        vC = 3.0 * pD + vc[t - 1]
        vD = 1.0 + 4.0 * pD + vd[t - 1]
        vd[t] = vC if vC >= vD else vD

    vC = 3.0 * p_now + vc[remaining - 1]
    vD = 1.0 + 4.0 * p_now + vd[remaining - 1]
    return 'D' if vD > vC else 'C'
